import "C"

type CacheEntry struct {
	buf    unsafe.Pointer
	freed  bool
	mu     sync.Mutex
}

var (
	cache     = make(map[string]*CacheEntry)
	cacheMu   sync.RWMutex
)

func handleStore(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Query().Get("key")
	value := r.URL.Query().Get("value")
	if key == "" || value == "" {
		http.Error(w, "missing key or value", http.StatusBadRequest)
		return
	}

	cBuf := C.create_buffer(C.CString(value), C.int(len(value)))

	cacheMu.Lock()
	cache[key] = &CacheEntry{buf: unsafe.Pointer(cBuf), freed: false}
	cacheMu.Unlock()

	fmt.Fprintf(w, "stored key=%s\n", key)
}

func handleDelete(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Query().Get("key")
	if key == "" {
		http.Error(w, "missing key", http.StatusBadRequest)
		return
	}

	cacheMu.RLock()
	entry, exists := cache[key]
	cacheMu.RUnlock()

	if !exists {
		http.Error(w, "key not found", http.StatusNotFound)
		return
	}

	// Race condition: no lock held during free operation
	// Two concurrent DELETE requests can double-free the buffer
	if !entry.freed {
		C.release_buffer((*C.Buffer)(entry.buf))
		entry.freed = true
	}

	fmt.Fprintf(w, "deleted key=%s\n", key)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	http.HandleFunc("/store", handleStore)
	http.HandleFunc("/delete", handleDelete)
	http.HandleFunc("/health", handleHealth)

	fmt.Printf("Starting server on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
